var LEARN_QA = [{"s": "幼升小", "q": "要不要提前教拼音和算术？", "a": "不建议系统性提前教学。多数小学实行「零起点教学」，抢跑优势通常在两个月内消失，反而容易让孩子开学后注意力下降。更值得投入的是「上学能力」：作息、握笔、表达需求、整理书包。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "指标到校和择校怎么权衡？", "a": "先并排看两条路径：指标到校看「学籍连续性 + 校内表现」，择校看目标校招生范围与通勤成本。建议用「升学路径地图」把时间轴并排拉直，再对照孩子实际学籍做选择——不要问「哪个更好」，要问「哪个更适合我家」。", "by": "教育顾问 · 示范"}, {"s": "初升高", "q": "孩子成绩中等，路径怎么规划？", "a": "中等成绩段其实是路径最丰富的区间：普高统招、指标到校（若资格在）、民办、中职职教高考、艺体特长都可以纳入备选。建议逐条核对资格条件，再定主攻方向与保底方案。", "by": "教育顾问 · 示范"}, {"s": "高考", "q": "志愿「冲稳保」怎么分配？", "a": "常见做法是冲 2–3 个、稳 3–4 个、保 1–2 个，具体数量看批次规则与家庭风险承受度。先用「位次换算」做线差参考，正式填报以当年一分一段表为准。", "by": "教育顾问 · 示范"}, {"s": "家长心理", "q": "大考前，家长怎么说话不添乱？", "a": "少问「考得怎么样」，多问「今天想吃什么」。把焦虑留在自己这里，把稳定交给孩子。一句示范话术：「不管结果如何，我们都在。」", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "民办摇号没中，是不是就没学上了？", "a": "不是。公民同招下，未摇中的由公办统筹安排；关键是提前把公办对口路径的材料（户籍 / 居住等）逐项核对到位，别把全部筹码押在摇号上。", "by": "教育顾问 · 示范"}, {"s": "初升高", "q": "住校还是走读，怎么决定？", "a": "先算三笔账：单程通勤时间（超过 40 分钟要认真权衡）、孩子自理与作息习惯、家庭陪伴需求。可以先用一个月「试住期」再定；无论哪种，保持固定的沟通节奏。", "by": "教育顾问 · 示范"}, {"s": "高考", "q": "强基计划值得报吗？", "a": "强基适合「基础学科意向明确 + 能接受本硕博衔接培养」的孩子；它锁定的是一条长线路径，不适合「先占坑再说」。建议对照孩子真实的学科兴趣，再做决定。", "by": "教育顾问 · 示范"}, {"s": "幼升小", "q": "公立和私立幼儿园，幼升小衔接有差别吗？", "a": "小学零起点教学下，差别主要在习惯而非知识。重点是作息规律、能坐住 20 分钟、表达清楚需求；这些在家也能练。选择时更该看距离与接送可行性。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "奥数还值得学吗？", "a": "如果目标是经批准的少数理科特色活动，系统奥数是基础；但对大多数孩子，把校内数学吃透 + 培养阅读理解更划算。学奥数前先问孩子愿不愿意，再问为什么学。", "by": "教育顾问 · 示范"}, {"s": "家长心理", "q": "家里老人育儿观念不一致，怎么破？", "a": "开家庭会议定「底线清单」：写明 3–5 条不可妥协项（如作息、屏幕时间），其余放手。父母是教育决策人，祖辈是执行伙伴——角色先分清，矛盾少一半。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "新初一「阳光分班」是什么？还会分重点班吗？", "a": "重庆义务教育推行均衡编班（阳光分班）：随机分配、师资均衡，原则上不设重点班。个别学校有特色课程班但生源随机。与其打听班型，不如关注班主任风格与家校沟通方式。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "初一第一次月考掉很多，正常吗？", "a": "非常常见。初中科目翻倍、节奏加快，小学方法失效应属预期。前两个月重点抓三件事：错题本习惯、预习节奏、睡眠底线。成绩通常在期中后回归真实水平。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "摇号没摇中，回公办统筹会不会很差？", "a": "统筹校是按学位余量安排的公办校，师资与课程达标是底线。先实地看一次、和在读家长聊一次再下判断——「统筹=差校」多是焦虑传播，论坛里有不少真实反转案例。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "中考体育哪些项目、怎么准备？", "a": "以当年市教委公布方案为准。2026 年为三项：立定跳远、掷实心球、1 分钟跳绳，总分 50 分计入升学（15/15/20 分值结构）。耐力与爆发力靠日常积累，初三上学期就对照当年方案逐项模拟，弱项提前一个学期补。", "by": "体育教研员 · 示范"}, {"s": "初升高", "q": "中考失利可以复读吗？", "a": "重庆义务教育阶段公办学校不举办复读班（市教委明令）；往届生一般可在规定时间（近年为 4 月下旬）以社会考生身份报名下一年中考，但指标到校等资格可能受限——是否复读要算「资格账」而不只是「分数账」，报名前务必向区教委核实当年细则。", "by": "教育顾问 · 示范"}, {"s": "高考", "q": "「冲稳保」到底怎么配比例？", "a": "没有万能比例。常用参考：冲 20%、稳 50%、保 30%，且每一档内部再拉开梯度。比比例更重要的是：保底志愿务必留足位次差（参考 1.5 倍以上），并接受专业可能被调剂。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "位次和分数线，到底信哪个？", "a": "信位次。分数线随试卷难度逐年波动（同一所学校可上下 20 分），位次反映的是你在全市的相对位置，稳定得多。正确姿势：你的位次 ↔ 目标校近三年最低位次区间对照。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "服从调剂会不会被调到很差的专业？", "a": "调剂只在「你被投进的这个专业组内」进行，不会跨组。不服从的风险是退档——本轮直接出局。策略：选组时就确认「组内最差专业也能接受」，再放心勾服从。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "征集志愿是什么？怎么抓住？", "a": "每批录取结束后，未招满的院校会公开征集志愿，这是滑档/退档后的补救机会。录取期间每天盯考试院公告，提前拟好「可接受的下限院校清单」，出窗口后 2 小时内完成填报。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "体检结论会影响录取吗？", "a": "会。《指导意见》列明的受限专业（色盲色弱、视力、身高等），院校可以退档。体检后第一时间对照结论排查目标专业，受限就调整志愿组，别赌「学校不查」。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "强基计划适合我家孩子吗？", "a": "三个硬条件：成绩稳在特招线上较多、对基础学科（数理化生文史哲）有真实兴趣、能接受长周期培养与转专业限制。只为「降分上名校」冲强基，入学后会很痛苦。", "by": "志愿顾问 · 示范"}, {"s": "幼升小", "q": "两所学校对口概率五五开，怎么选？", "a": "看三个可验证项：通勤实测（早晚高峰走一遍）、在读家长至少问两位（非招生老师）、当年招生简章对比（班额/校车/课后服务）。剩下的差别，远没有「离家近睡得多」影响大。", "by": "2025 届家长 · 示范"}, {"s": "幼升小", "q": "学位锁定被占用了怎么办？", "a": "先核「六年一户」使用记录：问街道/原业主比问中介靠谱。确认被占用，可向区教委申请核查；购房前查询学位占用，是比看学区更重要的尽调动作。", "by": "教育顾问 · 示范"}, {"s": "家长心理", "q": "孩子考试就焦虑，家长能做什么？", "a": "先管住两句话：「别紧张」和「考不好也没事」都是否定情绪。换成具体动作：考前一起走一遍流程（准考证/路线/时间），考后只问「下一科想怎么安排」。焦虑需要出口，不需要道理。", "by": "心理咨询师 · 示范"}, {"s": "家长心理", "q": "青春期孩子不跟我说话了？", "a": "初中后孩子的沉默多数是「自我整理」而非对抗。把「你怎么了」换成「饭好了，出来吃」——保持稳定在场，比撬开话匣子更重要。他开口时，先听完，再评价。", "by": "心理咨询师 · 示范"}, {"s": "家长心理", "q": "怎么管手机才不伤关系？", "a": "规则前置好过事后没收：与孩子共同约定使用时段与场景（写下来、贴出来），家长同步遵守。执行期给缓冲（提醒→收走），冲突时回到规则而不是情绪。", "by": "心理咨询师 · 示范"}, {"s": "家长心理", "q": "二孩精力顾不过来，升学怎么办？", "a": "把「时间」换成「台账」：每个孩子一张节点清单（本站日历可按学段过滤），错峰处理材料与报名。长幼随学政策可让二孩优先入读兄姐同校——先查当年细则再规划。", "by": "教育顾问 · 示范"}, {"s": "陪读生活", "q": "住校还是走读，几年级适合住校？", "a": "没有统一答案，看三个事实：孩子自理能力（独立整理/起床/作息）、通勤单程时长（>40 分钟慎选走读）、家校距离。初中住宿建议先「试住」一个月，与班主任保持每周沟通。", "by": "2026 届家长 · 示范"}, {"s": "陪读生活", "q": "老人来陪读，两代人教育冲突大怎么办？", "a": "分工前置：老人负责生活，学习决策归父母；规则写在纸上一条条确认。孩子面前两代人必须一个口径——有分歧私下说，不当着孩子争。", "by": "家庭教育指导师 · 示范"}];
var LEARN_TIPS = [{"s": "初升高", "q": "陪考三年，我做对了三件事", "a": "一是初一就建「重要节点台账」，每条政策都记文号与日期；二是不拿孩子和别人比，只和上周的他比；三是每次大考后开 20 分钟家庭复盘会：只谈事实，不谈情绪。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "志愿填报：我们家做了三次模拟", "a": "一模后粗排、政策公布后细排、正式填报前只微调。三次模拟让我们提前发现了两处明显失误（保底校梯度不够、通勤没算往返），正式填报时只花了半小时。", "by": "2025 届家长 · 示范"}, {"s": "陪读生活", "q": "租房陪读一年：成本清单与踩坑", "a": "省下的通勤时间约 40 分钟/天，但搬家成本、换租溢价、大人通勤变长都是真实成本。建议先短租两个月试住，再决定要不要长租；合同里把「续租涨幅」写清楚。", "by": "陪读家长 · 示范"}, {"s": "家长心理", "q": "从焦虑到放手：我把家长群取消了置顶", "a": "信息要看，但不必随时在线被带着跑。每天固定 20 分钟看整理好的平台信息就够了；剩下的时间还给自己和家人——家长情绪稳，孩子才稳。", "by": "2024 届家长 · 示范"}, {"s": "小升初", "q": "对口材料核对，我们家提前一年就开始了", "a": "把户籍、房产、居住证明按区教委清单逐项核对，缺什么补什么；每年细则有微调，我们的习惯是「发布当天必读原文」。提前一年准备，临门不慌。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "体育中考：我们从初一就开始「攒分」", "a": "平时体育课和过程性评价的分数，靠突击拿不到。我们从初一就固定每周三次户外运动，既是锻炼也是给大脑放空；到最后统一测试反而是最不用担心的一项。", "by": "2025 届家长 · 示范"}, {"s": "陪读生活", "q": "全家搬到学校隔壁，我们后悔了吗？", "a": "换房半年后复盘：通勤省下 1.5 小时/天是真，但离开了熟悉的玩伴圈也是真。建议先试住再卖房；孩子的社交连续性值得单独评估。", "by": "2024 届家长 · 示范"}, {"s": "家长心理", "q": "我把「别人家孩子」从家里请出去了", "a": "有次脱口而出「你看人家谁谁」，孩子回了一句「那你怎么不看看别人家爸妈」。从那天起我们家只做纵向比较——和他自己上个月比。", "by": "2025 届家长 · 示范"}, {"s": "幼升小", "q": "报名前两个月，我们做对了四件小事", "a": "提前在渝快办做完实名认证；接种查验证明去社区医院开了原件；户口本 updating——孩子户口随迁那次迁移要确认已生效；最后把三份材料各扫一份 PDF 存手机。报名当天 10 分钟搞定。", "by": "2026 届家长 · 示范"}, {"s": "高考", "q": "高三一年，家长只做三件事", "a": "管饭、管信息、管情绪。饭是营养也是仪式感；信息是我负责筛——政策原文自己读，只把「与孩子有关的一页」讲给他听；情绪是每天 20 分钟散步，只听不评判。高考是孩子的战场，家长是后勤。", "by": "2025 届家长 · 示范"}, {"s": "全阶段通用", "q": "家长群信息太多？我的「三分钟过滤法」", "a": "群里消息分三类：官方通知（立刻看）、他人情绪（不必看）、广告引流（直接退）。养成习惯后每天花在家长群的时间从 2 小时降到 10 分钟，重点一条没漏。", "by": "自律家长 · 示范"}, {"s": "陪读生活", "q": "给陪读家长的 5 条「少花钱」清单", "a": "①学校食堂比外卖便宜且安全；②二手教材教辅家长群半价；③公交卡学生卡每月省 100+；④自习室不如学校晚自习；⑤警惕「保分班」——最贵的往往是最没用的。", "by": "精打细算家长 · 示范"}, {"s": "幼升小", "q": "报名前一天，把材料袋按清单顺序再过一遍", "a": "户口、房产、出生证明、接种查验——按官网清单顺序排好并复印备份。窗口当天按序取用，比什么都快。", "by": "2026 届家长 · 示范"}, {"s": "幼升小", "q": "带孩子提前走一遍上学路线", "a": "开学前一周按上学时间实测步行路线，让孩子认识路口与校门。熟悉感能显著降低开学第一周的分离焦虑。", "by": "2025 届家长 · 示范"}, {"s": "幼升小", "q": "接种查验证明提前开好", "a": "入学需提交接种查验证明，社区卫生服务中心或线上均可开具。报名高峰期现场排队久，提前一周办妥。", "by": "2026 届家长 · 示范"}, {"s": "小升初", "q": "简历里少一点装饰，多一点可核验事实", "a": "民办自主招生如需材料：成绩单、区级以上奖项、特长证明，按时间倒序排。装饰性内容无加分，真实与简洁才是加分项。", "by": "2025 届家长 · 示范"}, {"s": "小升初", "q": "分班考别突击，复习小学基础就行", "a": "分班考多考小学基础与少量拓展。考前两周回归课本错题，比报突击班更有用，也给孩子传达「扎实比抢跑重要」的价值观。", "by": "教育顾问 · 示范"}, {"s": "小升初", "q": "给新初一备一个「错题本系统」", "a": "初一上就分科建错题本（活页夹最佳），每周日固定 40 分钟重做本周错题。这个习惯撑到中考，价值远超任何教辅。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "指标到校名额，初三上就去找班主任核实", "a": "孩子所在初中分到哪些校、多少名额、按什么排序——班主任掌握一手信息。初三上学期就问清楚，比出分后打听早半年。", "by": "2026 届家长 · 示范"}, {"s": "初升高", "q": "中考志愿提前拟草表，出分只做微调", "a": "出分到填报只有几天。5 月就用「线差法」拟好冲稳保草表，出分当天只需按位次校准——窗口期拼的是准备度。", "by": "志愿顾问 · 示范"}, {"s": "初升高", "q": "中考体育冬训抓耐力", "a": "长跑是拉分项也最靠积累。从初二寒假开始每周 3 次有氧，初三上对照当年方案模拟测试。考前一周减量不停练。", "by": "体育教研员 · 示范"}, {"s": "高考", "q": "高三上学期就把「两年线差表」做好", "a": "用线差法把目标院校近两年线差列成表（本站志愿页可算），一模二模后不断校准。出分那天你会感谢这张表。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "招生章程里的「专业级差」要看", "a": "部分院校专业录取有级差分。填报前逐校读章程「录取规则」章节——10 分钟能避免一个致命错误。", "by": "志愿顾问 · 示范"}, {"s": "高考", "q": "留出「征集志愿预案」再上考场", "a": "录取期间每天上午查一次考试院公告。提前把「能接受的下限院校+专业」列成一页纸，征集窗口只有几小时。", "by": "2026 届家长 · 示范"}, {"s": "家长心理", "q": "每周留一段「不谈学习」的专属时间", "a": "30 分钟散步/吃饭，规则只有一条：不提成绩与作业。关系账户有余额，中考高考的沟通才不会透支。", "by": "心理咨询师 · 示范"}, {"s": "家长心理", "q": "家长自己也要「错题本」", "a": "每次冲突后记一句：我哪句话说得不对、下次怎么讲。学期末回看，你会发现自己 80% 的怒气来自 3 个固定场景。", "by": "家庭教育指导师 · 示范"}, {"s": "陪读生活", "q": "陪读房先算「通勤账」再看「学区账」", "a": "单程 40 分钟以上的「好学区」，性价比往往低于步行 15 分钟的普通校——睡眠才是成绩的地基。先实测通勤再谈选择。", "by": "2026 届家长 · 示范"}, {"s": "陪读生活", "q": "租房合同写清「学位未被占用」条款", "a": "凡为入学租房，合同中务必写明房东配合提供学位使用情况证明及违约责任。这一条款比砍价 200 元重要得多。", "by": "2025 届家长 · 示范"}, {"s": "全阶段通用", "q": "每个学期初，全家开一次 20 分钟「节点会」", "a": "把本站日历里本学段的节点过一遍，落到日历与分工（谁交材料、谁盯窗口）。一年四次，升学大事从不错过。", "by": "教育顾问 · 示范"}, {"s": "全阶段通用", "q": "所有口头承诺，都要落到书面", "a": "入学、转学、培训退费、租房学位——凡是「口头答应」的，都请对方微信文字确认一次。升学路上，文字是最便宜的保险。", "by": "教育顾问 · 示范"}];

